  const expected = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "claude", model: "inline-claude" },
      { adapter: "codex", model: "inline-codex" },
      { adapter: "agy", model: "local-agy" },
      { adapter: "pi", model: "inline-pi" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  const resolved = await loadProfileBundle(bundlePath, "child");
  assert.deepEqual(resolved, expected);
  assert.equal("maxBudgetUsd" in resolved.participants![0], false);
  assert.equal("bin" in resolved.participants![1], false);
  assert.deepEqual((await loadProfileBundle(bundlePath, "singleton")).participants, [
    { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
    { adapter: "codex", model: "singleton-codex" },
