    timeoutMinutes: 10,
    repo: "../base",
    participants: [
      { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
      { adapter: "codex", model: "base-codex" },
    ],
    judge: { adapter: "pi", model: "base-judge" },
  });
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await Promise.all([basePath, localPath].map((path) => readFile(path))), originalYaml);
});

