test("applies inline overrides after inherited and local YAML, with independently owned results", async (t) => {
  const { bundlePath } = await fixture(t);
  const configs = join(dirname(bundlePath), "configs");
  const basePath = join(configs, "base.yaml");
  const localPath = join(configs, "local.yaml");
  await Promise.all([
    writeFile(basePath, `rounds: 1
timeoutMinutes: 10
repo: ../base
participants:
  - adapter: claude
    model: base-claude
    maxBudgetUsd: 7
  - adapter: codex
    model: base-codex
judge:
  adapter: pi
  model: base-judge
`),
    writeFile(localPath, `rounds: 2
repo: ../local
participants:
  - adapter: codex
    model: local-codex
    bin: local-bin
  - adapter: agy
    model: local-agy
judge:
  adapter: codex
  model: local-judge
`),
  ]);
  const overrides = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/base.yaml" },
      child: { extends: "base", config: "configs/local.yaml", overrides },
      singleton: { extends: "base", overrides: { participants: [{ adapter: "codex", model: "singleton-codex" }] } },
      emptyParticipants: { extends: "base", overrides: { participants: [] } },
      noJudge: { extends: "child", overrides: { judge: null } },
      localNoJudge: { config: "configs/local.yaml", overrides: { judge: null } },
      inlineOnly: { overrides: { rounds: 0, judge: null } },
      empty: { overrides: {} },
    },
  }));
  const originalBundle = await readFile(bundlePath);
  const originalYaml = await Promise.all([basePath, localPath].map((path) => readFile(path)));
  const expected = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  const resolved = await loadProfileBundle(bundlePath, "child");
  assert.deepEqual(resolved, expected);
  assert.equal(resolved.participants!.some(({ adapter }) => adapter === "claude" || adapter === "agy"), false);
  await assert.rejects(loadProfileBundle(bundlePath, "singleton"), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "emptyParticipants"), /at least 2 participants/);
  const withoutJudge = await loadProfileBundle(bundlePath, "noJudge");
  assert.deepEqual({ ...withoutJudge, judge: undefined }, { ...expected, judge: undefined });
  assert.equal("judge" in withoutJudge, false);
  assert.equal("judge" in await loadProfileBundle(bundlePath, "localNoJudge"), false);
  assert.deepEqual(await loadProfileBundle(bundlePath, "inlineOnly"), { rounds: 0 });
  assert.deepEqual(await loadProfileBundle(bundlePath, "empty"), {});

  resolved.rounds = 99;
  resolved.participants![0].model = "mutated";
  resolved.participants!.push({ adapter: "copilot-cli" });
  resolved.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "child"), expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), {
    rounds: 1,
    timeoutMinutes: 10,
    repo: "../base",
    participants: [
      { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
      { adapter: "codex", model: "base-codex" },
    ],
    judge: { adapter: "pi", model: "base-judge" },
  });
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await Promise.all([basePath, localPath].map((path) => readFile(path))), originalYaml);
});

test("rejects malformed inline overrides with INVALID_BUNDLE", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalidOverrides = [
    null, [], "not-an-object", 1,
    { unknown: true },
    { rounds: "2" }, { rounds: true }, { rounds: -1 }, { rounds: 1.5 },
    { repo: 1 }, { repo: "comment # is not lossless" }, { repo: "two\nlines" },
    { timeoutMinutes: "10" }, { timeoutMinutes: false },
    { participants: null }, { participants: {} }, { participants: "claude" },
    { participants: [null] }, { participants: [{}] },
    { participants: [{ adapter: "unknown" }] },
    { participants: [{ adapter: 1 }] },
    { participants: [{ adapter: "claude", model: 1 }] },
    { participants: [{ adapter: "claude", model: '"already quoted"' }] },
    { participants: [{ adapter: "claude", bin: 1 }] },
    { participants: [{ adapter: "claude", maxBudgetUsd: "1" }] },
    { participants: [{ adapter: "claude", effort: 1 }] },
    { participants: [{ adapter: "claude", extra: true }] },
    { judge: [] }, { judge: "pi" }, { judge: {} },
    { judge: { adapter: "unknown" } }, { judge: { adapter: "pi", model: 1 } },
    { judge: { adapter: "pi", extra: true } },
  ];
  for (const overrides of invalidOverrides) {
    const text = JSON.stringify({ version: 1, profiles: { fast: { overrides } } });
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { name: "Error", code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

