      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  const resolved = await loadProfileBundle(bundlePath, "child");
  assert.deepEqual(resolved, expected);
  assert.equal(resolved.participants!.some(({ adapter }) => adapter === "claude" || adapter === "agy"), false);
  await assert.rejects(loadProfileBundle(bundlePath, "singleton"), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "emptyParticipants"), /at least 2 participants/);
  const withoutJudge = await loadProfileBundle(bundlePath, "noJudge");
  assert.deepEqual({ ...withoutJudge, judge: undefined }, { ...expected, judge: undefined });
  assert.equal("judge" in withoutJudge, false);
  assert.equal("judge" in await loadProfileBundle(bundlePath, "localNoJudge"), false);
  assert.deepEqual(await loadProfileBundle(bundlePath, "inlineOnly"), { rounds: 0 });
  assert.deepEqual(await loadProfileBundle(bundlePath, "empty"), {});

  resolved.rounds = 99;
  resolved.participants![0].model = "mutated";
  resolved.participants!.push({ adapter: "copilot-cli" });
  resolved.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "child"), expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), {
    rounds: 1,
    timeoutMinutes: 10,
    repo: "../base",
    participants: [
      { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
      { adapter: "codex", model: "base-codex" },
    ],
    judge: { adapter: "pi", model: "base-judge" },
  });
