#!/usr/bin/env node
// Render a bundle profile for use with Disputatio's normal --config option.
import { serializeDebateConfig } from "./config.ts";
import { loadProfileBundle } from "./profile-bundle.ts";

function argumentError(message: string): Error {
  return new Error(`${message}\nUsage: node src/profile-cli.ts --bundle FILE [--profile NAME]`);
}

function parseArgs(args: string[]): { bundlePath: string; profileName?: string } {
  let bundlePath: string | undefined;
  let profileName: string | undefined;
  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    if (flag !== "--bundle" && flag !== "--profile") {
      throw argumentError(`Unknown argument: ${flag}`);
    }
    const value = args[++i];
    if (!value || value.startsWith("-")) {
      throw argumentError(`Missing value for ${flag}`);
    }
    if (flag === "--bundle") {
      if (bundlePath !== undefined) throw argumentError("Repeated --bundle argument");
      bundlePath = value;
    } else {
      if (profileName !== undefined) throw argumentError("Repeated --profile argument");
      profileName = value;
    }
  }
  if (bundlePath === undefined) throw argumentError("Missing required --bundle FILE argument");
  return { bundlePath, profileName };
}

try {
  const { bundlePath, profileName } = parseArgs(process.argv.slice(2));
  const config = await loadProfileBundle(bundlePath, profileName);
  // Complete loading and serialization before emitting anything to stdout.
  const yaml = serializeDebateConfig(config);
  process.stdout.write(yaml);
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  const code = error !== null && typeof error === "object" && "code" in error
    ? `${String(error.code)}: `
    : "";
  console.error(`profile-cli: ${code}${message}`);
  process.exitCode = 1;
}
import { readFile, realpath } from "node:fs/promises";
import { dirname, isAbsolute, relative, resolve, sep } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { parseDebateConfigOverlay, serializeDebateConfig, type DebateConfig } from "./config.ts";

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function bundleError(
  code: "INVALID_BUNDLE" | "UNKNOWN_PROFILE" | "PROFILE_REQUIRED" | "PROFILE_CYCLE" | "UNSAFE_CONFIG_PATH",
  message: string,
): Error {
  return Object.assign(new Error(message), { code });
}

function validateOverrideSpec(value: unknown): void {
  if (!isObject(value) || typeof value.adapter !== "string") {
    throw bundleError("INVALID_BUNDLE", "Override participant and judge specs must be objects with an adapter");
  }
  for (const [key, field] of Object.entries(value)) {
    const valid = key === "maxBudgetUsd"
      ? typeof field === "number" && Number.isFinite(field)
      : ["adapter", "model", "bin", "effort"].includes(key) && typeof field === "string";
    if (!valid) throw bundleError("INVALID_BUNDLE", `Invalid override spec field: ${key}`);
  }
}

function parseOverrides(value: unknown): { config: DebateConfig; removeJudge: boolean } {
  if (!isObject(value)) throw bundleError("INVALID_BUNDLE", "Profile overrides must be an object");
  // The serializer intentionally emits only supported fields. Check the JSON
  // shape first so unknown keys and wrong types cannot disappear or be coerced.
  for (const [key, field] of Object.entries(value)) {
    switch (key) {
      case "rounds":
      case "timeoutMinutes":
        if (typeof field !== "number" || !Number.isFinite(field)) {
          throw bundleError("INVALID_BUNDLE", `Override ${key} must be a finite number`);
        }
        break;
      case "repo":
        if (typeof field !== "string") throw bundleError("INVALID_BUNDLE", "Override repo must be a string");
        break;
      case "participants":
        if (!Array.isArray(field)) throw bundleError("INVALID_BUNDLE", "Override participants must be an array");
        for (const spec of field) validateOverrideSpec(spec);
        break;
      case "judge":
