test("lists profile names in Unicode code-point order without loading or validating profiles", async (t) => {
  const { bundlePath } = await fixture(t);
  const profiles = {
    z: null,
    "\u{10000}": { extends: "absent" },
    "\uE000": { config: "../outside.yaml" },
    a: { config: "configs/missing.yaml" },
    A: { unexpected: true },
  };
  const text = JSON.stringify({ version: 1, profiles });
  await writeFile(bundlePath, text);

  // A UTF-16 sort puts U+10000 before U+E000. The public listing is instead
  // ordered by Unicode scalar value, so BMP private-use precedes U+10000.
  const expected = ["A", "a", "z", "\uE000", "\u{10000}"];
  const first = await listProfiles(bundlePath);
  assert.deepEqual(first, expected);
  first.reverse();
  assert.deepEqual(await listProfiles(bundlePath), expected, "each call returns a fresh array");
  assert.equal(await readFile(bundlePath, "utf8"), text);
});

