import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { parseDebateConfigOverlay, type DebateConfig } from "./config.ts";

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function bundleError(code: "INVALID_BUNDLE" | "UNKNOWN_PROFILE", message: string): Error {
  return Object.assign(new Error(message), { code });
}

function overlayConfig(parent: DebateConfig, child: DebateConfig): DebateConfig {
  const result = { ...parent, ...child };
  if (child.participants && parent.participants) {
    const replacements = new Map(child.participants.map((spec) => [spec.adapter, spec]));
    result.participants = parent.participants.map((spec) => replacements.get(spec.adapter) ?? spec);
    const inheritedAdapters = new Set(parent.participants.map((spec) => spec.adapter));
    for (const spec of replacements.values()) {
      if (!inheritedAdapters.has(spec.adapter)) result.participants.push(spec);
    }
  }
  return result;
}

export async function loadProfileBundle(bundlePath: string, profileName: string): Promise<DebateConfig> {
  const absoluteBundlePath = resolve(bundlePath);
  const text = await readFile(absoluteBundlePath, "utf8");
  let bundle: unknown;
  try {
    bundle = JSON.parse(text);
  } catch {
    throw bundleError("INVALID_BUNDLE", `Invalid JSON in profile bundle: ${bundlePath}`);
  }
  if (!isObject(bundle) || bundle.version !== 1 || !isObject(bundle.profiles)) {
    throw bundleError("INVALID_BUNDLE", "Profile bundle must have version 1 and a profiles object");
  }
  const profiles = bundle.profiles;
  const visiting = new Set<string>();
  async function loadProfile(name: string): Promise<DebateConfig> {
    if (!Object.hasOwn(profiles, name)) {
      throw bundleError("UNKNOWN_PROFILE", `Unknown profile: ${name}`);
    }
    if (visiting.has(name)) {
      throw bundleError("INVALID_BUNDLE", `Profile inheritance cycle: ${[...visiting, name].join(" -> ")}`);
    }
    const profile = profiles[name];
    if (!isObject(profile)) {
      throw bundleError("INVALID_BUNDLE", `Profile ${name} must be an object`);
    }
    const hasConfig = Object.hasOwn(profile, "config");
    const hasParent = Object.hasOwn(profile, "extends");
    if ((!hasConfig && !hasParent)
      || (hasConfig && (typeof profile.config !== "string" || profile.config.trim() === ""))
      || (hasParent && (typeof profile.extends !== "string" || profile.extends.trim() === ""))) {
      throw bundleError("INVALID_BUNDLE", `Profile ${name} must have a non-empty config path or extends name`);
    }
    visiting.add(name);
    const parent = hasParent ? await loadProfile(profile.extends as string) : {};
    let config = parent;
    if (hasConfig) {
      const configPath = resolve(dirname(absoluteBundlePath), profile.config as string);
      config = overlayConfig(parent, parseDebateConfigOverlay(await readFile(configPath, "utf8")));
    }
    visiting.delete(name);
    return config;
  }

  // No cache or writes: every load owns its entire resolved configuration.
  const config = await loadProfile(profileName);
  if (config.participants && config.participants.length < 2) {
    throw new Error(`debate config: a debate needs at least 2 participants (got ${config.participants.length})`);
  }
  return config;
}
