import { test, type TestContext } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, relative } from "node:path";
import { parseDebateConfig } from "../src/config.ts";
import { loadProfileBundle } from "../src/profile-bundle.ts";

const yaml = `rounds: 2
repo: ../project
participants:
  - adapter: claude
    model: fast-model
  - adapter: codex
judge:
  adapter: pi
`;

async function fixture(t: TestContext) {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-bundle-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  await mkdir(join(dir, "configs"));
  const configPath = join(dir, "configs", "fast.yaml");
  const bundlePath = join(dir, "bundle.json");
  await writeFile(configPath, yaml);
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { fast: { config: "configs/fast.yaml" } } }));
  return { configPath, bundlePath };
}

test("loads config relative to the bundle, preserves inputs, and owns each result", async (t) => {
  const { configPath, bundlePath } = await fixture(t);
  const originalBundle = await readFile(bundlePath);
  const originalConfig = await readFile(configPath);
  const first = await loadProfileBundle(relative(process.cwd(), bundlePath), "fast");
  assert.deepEqual(first, parseDebateConfig(yaml));
  first.rounds = 99;
  first.participants![0].model = "changed";
  first.participants!.push({ adapter: "pi" });
  first.judge!.adapter = "codex";
  assert.deepEqual(await loadProfileBundle(bundlePath, "fast"), parseDebateConfig(yaml));
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await readFile(configPath), originalConfig);
});

test("rejects invalid bundles and malformed selected profiles with INVALID_BUNDLE", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalid = [
    "{", "null", "[]", "1",
    ...[
      {}, { version: 2, profiles: {} }, { version: "1", profiles: {} },
      ...[undefined, null, [], "profiles", 1].map((profiles) => ({ version: 1, profiles })),
      ...[null, [], "fast", {}, { config: null }, { config: 1 }, { config: "" }, { config: "  " }]
        .map((fast) => ({ version: 1, profiles: { fast } })),
    ].map((value) => JSON.stringify(value)),
  ];
  for (const text of invalid) {
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { name: "Error", code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("unknown profiles include inherited property names", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const name of ["missing", "toString", "constructor", "__proto__"]) {
    await assert.rejects(loadProfileBundle(bundlePath, name), { name: "Error", code: "UNKNOWN_PROFILE" });
  }
});

test("validates only the selected profile, including own special property names", async (t) => {
  const { bundlePath } = await fixture(t);
  await writeFile(bundlePath, '{"version":1,"profiles":{"bad":null,"__proto__":{"config":"configs/fast.yaml"}}}');
  assert.deepEqual(await loadProfileBundle(bundlePath, "__proto__"), parseDebateConfig(yaml));
});

test("preserves missing-file errors and existing YAML parse errors", async (t) => {
  const { configPath, bundlePath } = await fixture(t);
  await writeFile(configPath, "rounds: -1\n");
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), {
    name: "Error", message: 'debate config: "rounds" must be a non-negative integer',
  });
  assert.equal(await readFile(configPath, "utf8"), "rounds: -1\n");
  await rm(configPath);
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "ENOENT" });
});

test("resolves inheritance chains with parent-first participant overlays and independently owned results", async (t) => {
  const { bundlePath } = await fixture(t);
  const configs = join(dirname(bundlePath), "configs");
  const basePath = join(configs, "base.yaml");
  const middlePath = join(configs, "middle.yaml");
  const childPath = join(configs, "child.yaml");
  const singleOverridePath = join(configs, "single-override.yaml");
  const base = `rounds: 2
timeoutMinutes: 10
repo: ../parent
participants:
  - adapter: claude
    model: parent-claude
    maxBudgetUsd: 7
  - adapter: codex
    model: parent-codex
    bin: parent-codex-bin
judge:
  adapter: pi
  model: parent-judge
  effort: high
`;
  const middle = `rounds: 3
participants:
  - adapter: claude
    model: middle-claude
  - adapter: agy
    model: middle-agy
judge:
  adapter: codex
  model: middle-judge
`;
  const child = `repo: ./child
participants:
  - adapter: codex
    model: child-codex
  - adapter: pi
    model: child-pi
  - adapter: copilot-cli
    model: child-copilot
`;
  const singleOverride = `participants:
  - adapter: codex
    model: child-codex
`;
  await Promise.all([
    writeFile(basePath, base),
    writeFile(middlePath, middle),
    writeFile(childPath, child),
    writeFile(singleOverridePath, singleOverride),
  ]);
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/base.yaml" },
      middle: { extends: "base", config: "configs/middle.yaml" },
      child: { extends: "middle", config: "configs/child.yaml" },
      inherited: { extends: "child" },
      singleOverride: { extends: "middle", config: "configs/single-override.yaml" },
    },
  }));

  assert.throws(() => parseDebateConfig(singleOverride), /at least 2 participants/);
  const expected = {
    rounds: 3,
    timeoutMinutes: 10,
    repo: "./child",
    participants: [
      { adapter: "claude", model: "middle-claude" },
      { adapter: "codex", model: "child-codex" },
      { adapter: "agy", model: "middle-agy" },
      { adapter: "pi", model: "child-pi" },
      { adapter: "copilot-cli", model: "child-copilot" },
    ],
    judge: { adapter: "codex", model: "middle-judge" },
  };
  const originalBundle = await readFile(bundlePath);
  const originalConfigs = await Promise.all([basePath, middlePath, childPath, singleOverridePath].map((path) => readFile(path)));
  const resolved = await loadProfileBundle(bundlePath, "child");
  assert.deepEqual(resolved, expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "inherited"), expected);
  assert.deepEqual((await loadProfileBundle(bundlePath, "singleOverride")).participants, [
    { adapter: "claude", model: "middle-claude" },
    { adapter: "codex", model: "child-codex" },
    { adapter: "agy", model: "middle-agy" },
  ]);

  // Matching adapters and the judge are whole-spec replacements, not field merges.
  assert.equal("maxBudgetUsd" in resolved.participants![0], false);
  assert.equal("bin" in resolved.participants![1], false);
  assert.deepEqual(resolved.judge, { adapter: "codex", model: "middle-judge" });
  assert.equal("effort" in resolved.judge!, false);

  resolved.rounds = 99;
  resolved.participants![0].model = "mutated";
  resolved.participants!.push({ adapter: "copilot-cli" });
  resolved.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "child"), expected);
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await Promise.all([basePath, middlePath, childPath, singleOverridePath].map((path) => readFile(path))), originalConfigs);
});

test("rejects malformed inheritance, unknown parents, and cycles", async (t) => {
  const { bundlePath } = await fixture(t);
  const malformedExtends = [null, [], {}, 1, "", "  "];
  for (const extendsValue of malformedExtends) {
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: { child: { extends: extendsValue, config: "configs/fast.yaml" } },
    }));
    await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "INVALID_BUNDLE" });
  }

  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: { child: { extends: "absent" } },
  }));
  await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "UNKNOWN_PROFILE" });

  for (const profiles of [
    { self: { extends: "self" } },
    { first: { extends: "second" }, second: { extends: "first" } },
  ]) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles }));
    const selected = Object.keys(profiles)[0];
    await assert.rejects(loadProfileBundle(bundlePath, selected), { code: "INVALID_BUNDLE" });
  }
});

test("rejects a final inherited configuration with only one participant", async (t) => {
  const { bundlePath } = await fixture(t);
  const singleton = "participants:\n  - adapter: claude\n";
  await writeFile(join(dirname(bundlePath), "configs", "singleton.yaml"), singleton);
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      singleton: { config: "configs/singleton.yaml" },
      inherited: { extends: "singleton" },
    },
  }));

  assert.throws(() => parseDebateConfig(singleton), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "inherited"), /at least 2 participants/);
});

