232	test("applies inline overrides after inherited and local YAML, with independently owned results", async (t) => {
233	  const { bundlePath } = await fixture(t);
234	  const configs = join(dirname(bundlePath), "configs");
235	  const basePath = join(configs, "base.yaml");
236	  const localPath = join(configs, "local.yaml");
237	  await Promise.all([
238	    writeFile(basePath, `rounds: 1
239	timeoutMinutes: 10
240	repo: ../base
241	participants:
242	  - adapter: claude
243	    model: base-claude
244	    maxBudgetUsd: 7
245	  - adapter: codex
246	    model: base-codex
247	judge:
248	  adapter: pi
249	  model: base-judge
250	`),
251	    writeFile(localPath, `rounds: 2
252	repo: ../local
253	participants:
254	  - adapter: codex
255	    model: local-codex
256	    bin: local-bin
257	  - adapter: agy
258	    model: local-agy
259	judge:
260	  adapter: codex
261	  model: local-judge
262	`),
263	  ]);
264	  const overrides = {
265	    rounds: 3,
266	    timeoutMinutes: 45,
267	    repo: "./inline",
268	    participants: [
269	      { adapter: "claude", model: "inline-claude" },
270	      { adapter: "codex", model: "inline-codex" },
271	      { adapter: "pi", model: "inline-pi" },
272	    ],
273	    judge: { adapter: "agy", model: "inline-judge" },
274	  };
275	  await writeFile(bundlePath, JSON.stringify({
276	    version: 1,
277	    profiles: {
278	      base: { config: "configs/base.yaml" },
279	      child: { extends: "base", config: "configs/local.yaml", overrides },
280	      singleton: { extends: "base", overrides: { participants: [{ adapter: "codex", model: "singleton-codex" }] } },
281	      noJudge: { extends: "child", overrides: { judge: null } },
282	      empty: { overrides: {} },
283	    },
284	  }));
285	  const originalBundle = await readFile(bundlePath);
286	  const expected = {
287	    rounds: 3,
288	    timeoutMinutes: 45,
289	    repo: "./inline",
290	    participants: [
291	      { adapter: "claude", model: "inline-claude" },
292	      { adapter: "codex", model: "inline-codex" },
293	      { adapter: "agy", model: "local-agy" },
294	      { adapter: "pi", model: "inline-pi" },
295	    ],
296	    judge: { adapter: "agy", model: "inline-judge" },
297	  };
298	  const resolved = await loadProfileBundle(bundlePath, "child");
299	  assert.deepEqual(resolved, expected);
300	  assert.equal("maxBudgetUsd" in resolved.participants![0], false);
301	  assert.equal("bin" in resolved.participants![1], false);
302	  assert.deepEqual((await loadProfileBundle(bundlePath, "singleton")).participants, [
303	    { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
304	    { adapter: "codex", model: "singleton-codex" },
305	  ]);
306	  const withoutJudge = await loadProfileBundle(bundlePath, "noJudge");
307	  assert.deepEqual({ ...withoutJudge, judge: undefined }, { ...expected, judge: undefined });
308	  assert.equal("judge" in withoutJudge, false);
309	  assert.deepEqual(await loadProfileBundle(bundlePath, "empty"), {});
310	
311	  resolved.rounds = 99;
312	  resolved.participants![0].model = "mutated";
313	  resolved.participants!.push({ adapter: "copilot-cli" });
314	  resolved.judge!.model = "mutated";
315	  assert.deepEqual(await loadProfileBundle(bundlePath, "child"), expected);
316	  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), {
317	    rounds: 1,
318	    timeoutMinutes: 10,
319	    repo: "../base",
320	    participants: [
321	      { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
322	      { adapter: "codex", model: "base-codex" },
323	    ],
324	    judge: { adapter: "pi", model: "base-judge" },
325	  });
326	  assert.deepEqual(await readFile(bundlePath), originalBundle);
327	});
