test("reports self and multi-profile inheritance cycles with PROFILE_CYCLE", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const profiles of [
    { self: { extends: "self" } },
    { first: { extends: "second" }, second: { extends: "first" } },
  ]) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles }));
    const selected = Object.keys(profiles)[0];
    await assert.rejects(loadProfileBundle(bundlePath, selected), { code: "PROFILE_CYCLE" });
  }
});

test("resolves very deep inheritance chains and detects deep cycles without overflowing the stack", async (t) => {
  const { bundlePath } = await fixture(t);
  const depth = 12_000;
  const chainProfiles: Record<string, unknown> = {
    base: { overrides: { rounds: 1 } },
  };
  for (let index = 0; index < depth; index += 1) {
    chainProfiles[`profile-${index}`] = { extends: index === 0 ? "base" : `profile-${index - 1}` };
  }
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: chainProfiles }));
  assert.deepEqual(await loadProfileBundle(bundlePath, `profile-${depth - 1}`), { rounds: 1 });

  const cycleProfiles: Record<string, unknown> = {};
  for (let index = 0; index < depth; index += 1) {
    cycleProfiles[`cycle-${index}`] = { extends: `cycle-${(index + 1) % depth}` };
  }
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: cycleProfiles }));
  await assert.rejects(loadProfileBundle(bundlePath, "cycle-0"), { code: "PROFILE_CYCLE" });
});

test("rejects final inherited configurations whose supplied participant list is too short", async (t) => {
  const { bundlePath } = await fixture(t);
  const singleton = "participants:\n  - adapter: claude\n";
  const empty = "participants:\n";
  await writeFile(join(dirname(bundlePath), "configs", "singleton.yaml"), singleton);
  await writeFile(join(dirname(bundlePath), "configs", "empty.yaml"), empty);
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/fast.yaml" },
      singleton: { extends: "base", config: "configs/singleton.yaml" },
      empty: { extends: "base", config: "configs/empty.yaml" },
    },
  }));

  assert.throws(() => parseDebateConfig(singleton), /at least 2 participants/);
  assert.throws(() => parseDebateConfig(empty), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "singleton"), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "empty"), /at least 2 participants/);
});

test("applies inline overrides after inherited and local YAML, with independently owned results", async (t) => {
  const { bundlePath } = await fixture(t);
  const configs = join(dirname(bundlePath), "configs");
  const basePath = join(configs, "base.yaml");
  const localPath = join(configs, "local.yaml");
  await Promise.all([
    writeFile(basePath, `rounds: 1
timeoutMinutes: 10
repo: ../base
participants:
  - adapter: claude
    model: base-claude
    maxBudgetUsd: 7
  - adapter: codex
    model: base-codex
judge:
  adapter: pi
  model: base-judge
`),
    writeFile(localPath, `rounds: 2
repo: ../local
participants:
  - adapter: codex
    model: local-codex
    bin: local-bin
  - adapter: agy
    model: local-agy
judge:
  adapter: codex
  model: local-judge
`),
  ]);
  const overrides = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/base.yaml" },
      child: { extends: "base", config: "configs/local.yaml", overrides },
      singleton: { extends: "base", overrides: { participants: [{ adapter: "codex", model: "singleton-codex" }] } },
      emptyParticipants: { extends: "base", overrides: { participants: [] } },
      noJudge: { extends: "child", overrides: { judge: null } },
      localNoJudge: { config: "configs/local.yaml", overrides: { judge: null } },
      inlineOnly: { overrides: { rounds: 0, judge: null } },
      empty: { overrides: {} },
    },
  }));
  const originalBundle = await readFile(bundlePath);
  const originalYaml = await Promise.all([basePath, localPath].map((path) => readFile(path)));
  const expected = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  const resolved = await loadProfileBundle(bundlePath, "child");
  assert.deepEqual(resolved, expected);
  assert.equal(resolved.participants!.some(({ adapter }) => adapter === "claude" || adapter === "agy"), false);
  await assert.rejects(loadProfileBundle(bundlePath, "singleton"), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "emptyParticipants"), /at least 2 participants/);
  const withoutJudge = await loadProfileBundle(bundlePath, "noJudge");
  assert.deepEqual({ ...withoutJudge, judge: undefined }, { ...expected, judge: undefined });
  assert.equal("judge" in withoutJudge, false);
  assert.equal("judge" in await loadProfileBundle(bundlePath, "localNoJudge"), false);
  assert.deepEqual(await loadProfileBundle(bundlePath, "inlineOnly"), { rounds: 0 });
  assert.deepEqual(await loadProfileBundle(bundlePath, "empty"), {});

  resolved.rounds = 99;
  resolved.participants![0].model = "mutated";
  resolved.participants!.push({ adapter: "copilot-cli" });
  resolved.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "child"), expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), {
    rounds: 1,
    timeoutMinutes: 10,
    repo: "../base",
    participants: [
      { adapter: "claude", model: "base-claude", maxBudgetUsd: 7 },
      { adapter: "codex", model: "base-codex" },
    ],
    judge: { adapter: "pi", model: "base-judge" },
  });
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await Promise.all([basePath, localPath].map((path) => readFile(path))), originalYaml);
});

test("rejects malformed inline overrides with INVALID_BUNDLE", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalidOverrides = [
    null, [], "not-an-object", 1,
    { unknown: true },
    { rounds: "2" }, { rounds: true }, { rounds: -1 }, { rounds: 1.5 },
    { repo: 1 }, { repo: "comment # is not lossless" }, { repo: "two\nlines" },
    { timeoutMinutes: "10" }, { timeoutMinutes: false },
    { participants: null }, { participants: {} }, { participants: "claude" },
    { participants: [null] }, { participants: [{}] },
    { participants: [{ adapter: "unknown" }] },
    { participants: [{ adapter: 1 }] },
    { participants: [{ adapter: "claude", model: 1 }] },
    { participants: [{ adapter: "claude", model: '"already quoted"' }] },
    { participants: [{ adapter: "claude", bin: 1 }] },
    { participants: [{ adapter: "claude", maxBudgetUsd: "1" }] },
    { participants: [{ adapter: "claude", effort: 1 }] },
    { participants: [{ adapter: "claude", extra: true }] },
    { judge: [] }, { judge: "pi" }, { judge: {} },
    { judge: { adapter: "unknown" } }, { judge: { adapter: "pi", model: 1 } },
    { judge: { adapter: "pi", extra: true } },
  ];
  for (const overrides of invalidOverrides) {
    const text = JSON.stringify({ version: 1, profiles: { fast: { overrides } } });
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { name: "Error", code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});
import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { parseDebateConfigOverlay, serializeDebateConfig, type DebateConfig } from "./config.ts";

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function bundleError(
  code: "INVALID_BUNDLE" | "UNKNOWN_PROFILE" | "PROFILE_REQUIRED" | "PROFILE_CYCLE",
  message: string,
): Error {
  return Object.assign(new Error(message), { code });
}

function validateOverrideSpec(value: unknown): void {
  if (!isObject(value) || typeof value.adapter !== "string") {
    throw bundleError("INVALID_BUNDLE", "Override participant and judge specs must be objects with an adapter");
  }
  for (const [key, field] of Object.entries(value)) {
    const valid = key === "maxBudgetUsd"
      ? typeof field === "number" && Number.isFinite(field)
      : ["adapter", "model", "bin", "effort"].includes(key) && typeof field === "string";
    if (!valid) throw bundleError("INVALID_BUNDLE", `Invalid override spec field: ${key}`);
  }
}

function parseOverrides(value: unknown): { config: DebateConfig; removeJudge: boolean } {
  if (!isObject(value)) throw bundleError("INVALID_BUNDLE", "Profile overrides must be an object");
  // The serializer intentionally emits only supported fields. Check the JSON
  // shape first so unknown keys and wrong types cannot disappear or be coerced.
  for (const [key, field] of Object.entries(value)) {
    switch (key) {
      case "rounds":
      case "timeoutMinutes":
        if (typeof field !== "number" || !Number.isFinite(field)) {
          throw bundleError("INVALID_BUNDLE", `Override ${key} must be a finite number`);
        }
        break;
      case "repo":
        if (typeof field !== "string") throw bundleError("INVALID_BUNDLE", "Override repo must be a string");
        break;
      case "participants":
        if (!Array.isArray(field)) throw bundleError("INVALID_BUNDLE", "Override participants must be an array");
        for (const spec of field) validateOverrideSpec(spec);
        break;
      case "judge":
        if (field !== null) validateOverrideSpec(field);
        break;
      default:
        throw bundleError("INVALID_BUNDLE", `Unknown override key: ${key}`);
    }
  }
  const removeJudge = value.judge === null;
  const candidate = { ...value };
  if (removeJudge) delete candidate.judge;
  try {
    const config = parseDebateConfigOverlay(serializeDebateConfig(candidate as DebateConfig));
    // The minimal YAML format cannot represent every JSON string losslessly.
    if (!isDeepStrictEqual(config, candidate)) {
      throw new Error("Override values cannot be represented losslessly by the config format");
    }
    return { config, removeJudge };
  } catch (error) {
    throw bundleError("INVALID_BUNDLE", `Invalid profile overrides: ${(error as Error).message}`);
  }
}

function overlayConfig(parent: DebateConfig, child: DebateConfig): DebateConfig {
  // Every supplied field replaces its inherited value, including the entire
  // participants list in its original order. Only omitted fields inherit.
  return { ...parent, ...child };
}

export async function loadProfileBundle(bundlePath: string, profileName?: string): Promise<DebateConfig> {
  const absoluteBundlePath = resolve(bundlePath);
  const text = await readFile(absoluteBundlePath, "utf8");
  let bundle: unknown;
  try {
    bundle = JSON.parse(text);
  } catch {
    throw bundleError("INVALID_BUNDLE", `Invalid JSON in profile bundle: ${bundlePath}`);
  }
  if (!isObject(bundle) || bundle.version !== 1 || !isObject(bundle.profiles)) {
    throw bundleError("INVALID_BUNDLE", "Profile bundle must have version 1 and a profiles object");
  }
