  await Promise.all([
    writeFile(basePath, base),
    writeFile(middlePath, middle),
    writeFile(childPath, child),
    writeFile(scalarOnlyPath, scalarOnly),
    writeFile(singletonPath, singleton),
  ]);
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/base.yaml" },
      middle: { extends: "base", config: "configs/middle.yaml" },
      child: { extends: "middle", config: "configs/child.yaml" },
      inherited: { extends: "child" },
      omittedParticipants: { extends: "child", config: "configs/scalar-only.yaml" },
      intermediateSingleton: { extends: "middle", config: "configs/singleton.yaml" },
      replacedAfterSingleton: { extends: "intermediateSingleton", config: "configs/child.yaml" },
    },
  }));

  assert.throws(() => parseDebateConfig(singleton), /at least 2 participants/);
  const expected = {
    rounds: 3,
    timeoutMinutes: 10,
    repo: "./child",
    participants: [
      { adapter: "pi", model: "child-pi" },
      { adapter: "codex", model: "child-codex" },
      { adapter: "copilot-cli", model: "child-copilot" },
    ],
    judge: { adapter: "codex", model: "middle-judge" },
  };
  const originalBundle = await readFile(bundlePath);
  const originalConfigs = await Promise.all([basePath, middlePath, childPath, scalarOnlyPath, singletonPath].map((path) => readFile(path)));
  const resolved = await loadProfileBundle(bundlePath, "child");
  assert.deepEqual(resolved, expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "inherited"), expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "omittedParticipants"), { ...expected, repo: "./child-scalar" });
  await assert.rejects(loadProfileBundle(bundlePath, "intermediateSingleton"), /at least 2 participants/);
  assert.deepEqual(await loadProfileBundle(bundlePath, "replacedAfterSingleton"), expected);

  // The child list keeps exactly its supplied members and order; scalar and judge precedence is unchanged.
  assert.equal(resolved.participants!.some(({ adapter }) => adapter === "claude" || adapter === "agy"), false);
  assert.deepEqual(resolved.judge, { adapter: "codex", model: "middle-judge" });
  assert.equal("effort" in resolved.judge!, false);

  resolved.rounds = 99;
  resolved.participants![0].model = "mutated";
  resolved.participants!.push({ adapter: "copilot-cli" });
  resolved.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "child"), expected);
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await Promise.all([basePath, middlePath, childPath, scalarOnlyPath, singletonPath].map((path) => readFile(path))), originalConfigs);
});

