    writeFile(basePath, `rounds: 1
timeoutMinutes: 10
repo: ../base
participants:
  - adapter: claude
    model: base-claude
    maxBudgetUsd: 7
  - adapter: codex
    model: base-codex
judge:
  adapter: pi
  model: base-judge
`),
    writeFile(localPath, `rounds: 2
repo: ../local
participants:
  - adapter: codex
    model: local-codex
    bin: local-bin
  - adapter: agy
    model: local-agy
judge:
  adapter: codex
  model: local-judge
`),
  ]);
  const overrides = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/base.yaml" },
      child: { extends: "base", config: "configs/local.yaml", overrides },
      singleton: { extends: "base", overrides: { participants: [{ adapter: "codex", model: "singleton-codex" }] } },
      emptyParticipants: { extends: "base", overrides: { participants: [] } },
      noJudge: { extends: "child", overrides: { judge: null } },
      localNoJudge: { config: "configs/local.yaml", overrides: { judge: null } },
      inlineOnly: { overrides: { rounds: 0, judge: null } },
      empty: { overrides: {} },
    },
  }));
  const originalBundle = await readFile(bundlePath);
  const originalYaml = await Promise.all([basePath, localPath].map((path) => readFile(path)));
  const expected = {
    rounds: 3,
    timeoutMinutes: 45,
    repo: "./inline",
    participants: [
      { adapter: "pi", model: "inline-pi" },
      { adapter: "codex", model: "inline-codex-first" },
      { adapter: "codex", model: "inline-codex-second" },
    ],
    judge: { adapter: "agy", model: "inline-judge" },
  };
  const resolved = await loadProfileBundle(bundlePath, "child");
