import { test, type TestContext } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, dirname, join, relative } from "node:path";
import { parseDebateConfig } from "../src/config.ts";
import { loadProfileBundle } from "../src/profile-bundle.ts";

const yaml = `rounds: 2
repo: ../project
participants:
  - adapter: claude
    model: fast-model
  - adapter: codex
judge:
  adapter: pi
`;

async function fixture(t: TestContext) {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-bundle-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  await mkdir(join(dir, "configs"));
  const configPath = join(dir, "configs", "fast.yaml");
  const bundlePath = join(dir, "bundle.json");
  await writeFile(configPath, yaml);
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { fast: { config: "configs/fast.yaml" } } }));
  return { configPath, bundlePath };
}

test("loads config relative to the bundle, preserves inputs, and owns each result", async (t) => {
  const { configPath, bundlePath } = await fixture(t);
  const originalBundle = await readFile(bundlePath);
  const originalConfig = await readFile(configPath);
  const first = await loadProfileBundle(relative(process.cwd(), bundlePath), "fast");
  assert.deepEqual(first, parseDebateConfig(yaml));
  first.rounds = 99;
  first.participants![0].model = "changed";
  first.participants!.push({ adapter: "pi" });
  first.judge!.adapter = "codex";
  assert.deepEqual(await loadProfileBundle(bundlePath, "fast"), parseDebateConfig(yaml));
  assert.deepEqual(await readFile(bundlePath), originalBundle);
  assert.deepEqual(await readFile(configPath), originalConfig);
});

test("rejects invalid bundles and malformed selected profiles with INVALID_BUNDLE", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalid = [
    "{", "null", "[]", "1",
    ...[
      {}, { version: 2, profiles: {} }, { version: "1", profiles: {} },
      ...[undefined, null, [], "profiles", 1].map((profiles) => ({ version: 1, profiles })),
      ...[null, [], "fast", {}, { config: null }, { config: 1 }, { config: "" }, { config: "  " }]
        .map((fast) => ({ version: 1, profiles: { fast } })),
    ].map((value) => JSON.stringify(value)),
  ];
  for (const text of invalid) {
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { name: "Error", code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("unknown profiles include inherited property names", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const name of ["missing", "toString", "constructor", "__proto__"]) {
    await assert.rejects(loadProfileBundle(bundlePath, name), { name: "Error", code: "UNKNOWN_PROFILE" });
  }
});

test("selects the default profile when omitted, while an explicit profile takes precedence", async (t) => {
  const { bundlePath } = await fixture(t);
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    defaultProfile: "fast",
    profiles: {
      fast: { config: "configs/fast.yaml" },
      inline: { overrides: { rounds: 0 } },
    },
  }));

  assert.deepEqual(await loadProfileBundle(bundlePath), parseDebateConfig(yaml));
  assert.deepEqual(await loadProfileBundle(bundlePath, "inline"), { rounds: 0 });
});

test("requires a profile when no default is configured and reports unknown profile sources consistently", async (t) => {
  const { bundlePath } = await fixture(t);
  await assert.rejects(loadProfileBundle(bundlePath), { code: "PROFILE_REQUIRED" });
  await assert.rejects(loadProfileBundle(bundlePath, "absent"), { code: "UNKNOWN_PROFILE" });

  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    defaultProfile: "absent",
    profiles: { fast: { config: "configs/fast.yaml" } },
  }));
  await assert.rejects(loadProfileBundle(bundlePath), { code: "UNKNOWN_PROFILE" });

  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: { child: { extends: "absent" } },
  }));
  await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "UNKNOWN_PROFILE" });
});

test("validates a non-string default only when it is selected", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const defaultProfile of [null, [], {}, 1]) {
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      defaultProfile,
      profiles: { fast: { config: "configs/fast.yaml" } },
    }));
    await assert.rejects(loadProfileBundle(bundlePath), { code: "INVALID_BUNDLE" });
    assert.deepEqual(await loadProfileBundle(bundlePath, "fast"), parseDebateConfig(yaml));
  }
});

test("validates only the selected profile, including own special property names", async (t) => {
  const { bundlePath } = await fixture(t);
  await writeFile(bundlePath, '{"version":1,"profiles":{"bad":null,"__proto__":{"config":"configs/fast.yaml"}}}');
  assert.deepEqual(await loadProfileBundle(bundlePath, "__proto__"), parseDebateConfig(yaml));
});

test("preserves missing-file errors and existing YAML parse errors", async (t) => {
  const { configPath, bundlePath } = await fixture(t);
  await writeFile(configPath, "rounds: -1\n");
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), {
    name: "Error", message: 'debate config: "rounds" must be a non-negative integer',
  });
  assert.equal(await readFile(configPath, "utf8"), "rounds: -1\n");
  await rm(configPath);
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "ENOENT" });
});

test("rejects absolute, escaping, and externally linked config paths with UNSAFE_CONFIG_PATH", async (t) => {
  const { configPath, bundlePath } = await fixture(t);
  const bundleDir = dirname(bundlePath);
  const siblingDir = join(dirname(bundleDir), `${basename(bundleDir)}-sibling`);
  const externalPath = join(siblingDir, "external.yaml");
  const externalDirectory = join(siblingDir, "directory");
  await mkdir(externalDirectory, { recursive: true });
  t.after(() => rm(siblingDir, { recursive: true, force: true }));
  await Promise.all([
    writeFile(externalPath, yaml),
    writeFile(join(externalDirectory, "external.yaml"), yaml),
    symlink(externalPath, join(bundleDir, "configs", "external-file.yaml")),
    symlink(externalDirectory, join(bundleDir, "configs", "external-directory")),
  ]);

  const unsafePaths = [
    configPath,
    externalPath,
    "../outside.yaml",
    `../${basename(siblingDir)}/external.yaml`,
    "configs/external-file.yaml",
    "configs/external-directory/external.yaml",
  ];
  for (const config of unsafePaths) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { unsafe: { config } } }));
    await assert.rejects(loadProfileBundle(bundlePath, "unsafe"), { code: "UNSAFE_CONFIG_PATH" });
  }
});

test("allows normalized and symlinked config paths that remain in the real bundle directory", async (t) => {
  const { bundlePath } = await fixture(t);
  const configs = join(dirname(bundlePath), "configs");
  await Promise.all([
    mkdir(join(configs, "foo")),
    symlink("fast.yaml", join(configs, "internal-link.yaml")),
  ]);

  for (const config of ["configs/foo/../fast.yaml", "configs/internal-link.yaml"]) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { fast: { config } } }));
    assert.deepEqual(await loadProfileBundle(bundlePath, "fast"), parseDebateConfig(yaml));
  }

  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { missing: { config: "configs/missing.yaml" } } }));
  await assert.rejects(loadProfileBundle(bundlePath, "missing"), { code: "ENOENT" });
});

test("uses the real bundle location for config boundaries and inherited configs", async (t) => {
  const { bundlePath } = await fixture(t);
  const bundleDir = dirname(bundlePath);
  const aliasDir = join(bundleDir, "alias");
  const aliasBundlePath = join(aliasDir, "bundle.json");
  const decoyConfig = `rounds: 99\n`;
