test("rejects malformed inheritance and unknown parents", async (t) => {
  const { bundlePath } = await fixture(t);
  const malformedExtends = [null, [], {}, 1, "", "  "];
  for (const extendsValue of malformedExtends) {
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: { child: { extends: extendsValue, config: "configs/fast.yaml" } },
    }));
    await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "INVALID_BUNDLE" });
  }

  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: { child: { extends: "absent" } },
  }));
  await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "UNKNOWN_PROFILE" });
});

test("reports self and multi-profile inheritance cycles with PROFILE_CYCLE", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const profiles of [
    { self: { extends: "self" } },
    { first: { extends: "second" }, second: { extends: "first" } },
  ]) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles }));
    const selected = Object.keys(profiles)[0];
    await assert.rejects(loadProfileBundle(bundlePath, selected), { code: "PROFILE_CYCLE" });
  }
});

test("resolves very deep inheritance chains and detects deep cycles without overflowing the stack", async (t) => {
  const { bundlePath } = await fixture(t);
  const depth = 12_000;
  const chainProfiles: Record<string, unknown> = {
    base: { overrides: { rounds: 1 } },
  };
  for (let index = 0; index < depth; index += 1) {
    chainProfiles[`profile-${index}`] = { extends: index === 0 ? "base" : `profile-${index - 1}` };
  }
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: chainProfiles }));
  assert.deepEqual(await loadProfileBundle(bundlePath, `profile-${depth - 1}`), { rounds: 1 });

  const cycleProfiles: Record<string, unknown> = {};
  for (let index = 0; index < depth; index += 1) {
    cycleProfiles[`cycle-${index}`] = { extends: `cycle-${(index + 1) % depth}` };
  }
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: cycleProfiles }));
  await assert.rejects(loadProfileBundle(bundlePath, "cycle-0"), { code: "PROFILE_CYCLE" });
});

test("rejects final inherited configurations whose supplied participant list is too short", async (t) => {
  const { bundlePath } = await fixture(t);
  const singleton = "participants:\n  - adapter: claude\n";
  const empty = "participants:\n";
  await writeFile(join(dirname(bundlePath), "configs", "singleton.yaml"), singleton);
  await writeFile(join(dirname(bundlePath), "configs", "empty.yaml"), empty);
  await writeFile(bundlePath, JSON.stringify({
    version: 1,
    profiles: {
      base: { config: "configs/fast.yaml" },
      singleton: { extends: "base", config: "configs/singleton.yaml" },
      empty: { extends: "base", config: "configs/empty.yaml" },
    },
  }));

  assert.throws(() => parseDebateConfig(singleton), /at least 2 participants/);
  assert.throws(() => parseDebateConfig(empty), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "singleton"), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "empty"), /at least 2 participants/);
});

